using System;
using System.IO;
using System.Linq;
using MET.Core;
public static class MetProgressionFocusedChecks {
 static int checks, failures;
 static Catalog catalog; static string recordsRoot;
 static void Check(bool ok,string label) {checks++;if(!ok){failures++;Console.WriteLine("PROGRESSION FAIL "+label);} }
 static bool Near(double a,double b)=>Math.Abs(a-b)<0.00001;
 static Game Fresh(long seed=8291) {var g=new Game(catalog,recordsRoot);g.new_game(seed,1000000);Check(g.select_block(0)=="","start Block");Check(g.choose_origin(g.s["origin_choices"][0].Text)=="","choose origin");g.s["block"]["reward_choices"]=V.Arr();g.s["block"]["bonus_wallet"]=V.Map();g.s["block"]["blueprint_levels"]=V.Map();return g;}
 static V Theme(Game g)=>g.s["block"]["theme"];
 static string Build(Game g,string kind,params string[] slots) {string tile=Rules.ids(g.s["cells"]).First(x=>g.s["cells"][x].Get("building","")==""&&!g.s["cells"][x]["traits"].Contains("tile.water")).Text;var p=g.create_building(kind,tile,"commons",true);p["slots"]=V.Map();p["slot_types"]=V.Map();for(int i=0;i<slots.Length;i++){p["slots"]["test:"+i]="";p["slot_types"]["test:"+i]=slots[i];}g.refresh_metrics();return p["id"].Text;}
 static double Rule(Game g,string bid,string rid,int count=1) {return Rules.bonus_rules(g,bid,count).First(x=>x["id"]==rid).Get("value",0).Double;}
 static V Offer(Game g,string id) {var e=V.Map("id",id,"status","offered","theme",Theme(g)["id"],"revealed_seconds",g.s["beta_time"]["local_elapsed_seconds"]);Theme(g)["events"].Add(e);Theme(g)["event_ids"].Add(id);return e;}
 static void Hold(Game g,double months,double food=1) {foreach(var group in g.s["groups"].Values)group["living"]=V.Map("food",food,"medical",1.0,"education",1.0,"commercial",1.0,"entertainment",1.0);g.s["simulation_tick"]=g.s["simulation_tick"].Long+1;g.s["local_hours"]=g.s["local_hours"].Double+months;g.s["beta_time"]["local_elapsed_seconds"]=g.s["beta_time"]["local_elapsed_seconds"].Double+months*Cycles.MONTH_SECONDS;g.s["audit"]=V.Map("hours",months,"resources",V.Map("food",V.Map("produced",100.0*months),"goods",V.Map("produced",8.0*months)),"commercial_service_people",48.0,"population_food_demand_rate",5.0);g.s["metrics"]["energy_ratio"]=1.0;Themes.tick(g,months*Cycles.MONTH_SECONDS);}
 static void Rewards() {
  var g=Fresh(81276);
  for(int count=0;count<4;count++) {
   var pool=V.From(new[]{"P01","P07","L05"}.Take(count));var reward=Bonus.draw(g,"variable:"+count,V.Arr(),V.Map("bonus_ids",pool));Check(reward["choices"].Count==Math.Max(1,count),"variable pool "+count);var rng=g.s["rng"].Duplicate(true);var reopened=Bonus.draw(g,"variable:"+count,V.Arr(),V.Map("bonus_ids",V.Arr("R10")));Check(reopened==reward&&g.s["rng"]==rng,"source id freezes candidates "+count);double dt=g.s["dt"].Double,cash=g.s["currency"].Double;string bid=reward["choices"][0]["bonus_id"].Text;Check(Bonus.choose(g,reward["reward_id"].Text,bid)=="","claim variable draft "+count);if(count==0)Check(Near(g.s["currency"].Double-cash,30)&&Near(g.s["dt"].Double,dt),"empty pool pays cash without DT");Check(Bonus.choose(g,reward["reward_id"].Text,bid)!="","claim once "+count);
  }
  var a=Bonus.draw(g,"annual:1",V.Arr(),V.Map("bonus_ids",V.Arr("P01")));var b=Bonus.draw(g,"population:32",V.Arr(),V.Map("bonus_ids",V.Arr("P01")));var c=Bonus.draw(g,"theme:M1",V.Arr(),V.Map("bonus_ids",V.Arr("P01")));Check(Bonus.pending(g).Count==3,"three simultaneous rewards retained");Check(Bonus.choose(g,c["reward_id"].Text,"P01")!="","FIFO order");var twin=new Game(catalog,recordsRoot){s=V.Parse(g.s.ToJson())};Check(Bonus.draw(twin,"population:32")["choices"]==b["choices"],"serialized state retains offer");int before=(int)g.s["block"]["bonus_wallet"].Get("P01",V.Map()).Get("charges",0).Long;foreach(var r in new[]{a,b,c})Check(Bonus.choose(g,r["reward_id"].Text,"P01")=="","same card legal across records");Check(g.s["block"]["bonus_wallet"]["P01"]["charges"].Long==before+3,"copies accumulate");
  g=Fresh();string first=Build(g,"workshop","Production","Production","Production"),second=Build(g,"workshop","Production");for(int i=0;i<4;i++)Bonus.grant(g,"P01","fixture:"+i);for(int i=0;i<3;i++)Check(Bonus.install(g,"P01","building",first,"test:"+i)=="","same host distinct slot copy "+i);Check(Bonus.install(g,"P01","building",second,"test:0")=="","second host gets first copy");Check(g.s["block"]["bonus_wallet"]["P01"]["charges"].Long==0,"exact copy consumption");Check(Near(Rule(g,"P01","P01.4",3),8.0/3),"duplicate x2 to x2.6667");Check(Near(Rule(g,"P01","P01.1",3),11.0/6),"side effects weighted");Check(g.clear_slot(first,"test:0")==""&&g.s["block"]["bonus_wallet"]["P01"]["charges"].Long==0,"uninstall does not refund");Bonus.grant(g,"P01","extra");Check(Bonus.install(g,"P01","building",first,"test:1")!=""&&g.s["block"]["bonus_wallet"]["P01"]["charges"].Long==1,"same slot no-op keeps copy");var home=Build(g,"homestead","Operations","Operations");Bonus.grant(g,"O02","structure:1");Bonus.grant(g,"O02","structure:2");Check(Bonus.install(g,"O02","building",home,"test:0")=="","first structure installs");Check(Bonus.install(g,"O02","building",home,"test:1")!=""&&g.s["block"]["bonus_wallet"]["O02"]["charges"].Long==1,"idempotent structure retains second copy");
  g=Fresh();var host=Build(g,"workshop","Production");Bonus.grant(g,"P01","owned");Bonus.install(g,"P01","building",host,"test:0");double initial=g.compiled["stats"][host]["output.goods"].Double;Check(Bonus.research_candidates(g,V.Arr("P01","P07")).Count==1,"research requires ownership");for(int level=1;level<=2;level++){var reward=Bonus.draw(g,"research:"+level,V.Arr(),V.Map("kind","research","bonus_ids",V.Arr("P01")));Check(reward["kind"]=="research"&&Bonus.choose(g,reward["reward_id"].Text,"P01")=="","research applies level "+level);Check(Bonus.blueprint_level(g,"P01")==level&&g.s["block"]["bonus_wallet"]["P01"]["charges"].Long==0,"blueprint upgrade consumes no copy "+level);Check(Near(Rule(g,"P01","P01.4"),2.0+level*0.2)&&Near(Rule(g,"P01","P01.1"),1.5),"declared research strength "+level);}Check(g.compiled["stats"][host]["output.goods"].Double>initial,"research immediately recompiles existing instance");var exhausted=Bonus.draw(g,"research:max",V.Arr(),V.Map("kind","research","bonus_ids",V.Arr("P01")));Check(exhausted["kind"]=="copy"&&Bonus.choose(g,exhausted["reward_id"].Text,"P01")=="","max research falls back to copy");Check(Near(Rule(g,"P01","P01.4",3),10.0/3),"blueprint first then duplicate strength");
  g=Fresh();Bonus.grant(g,"P01","stale:owned");g.s["block"]["blueprint_levels"]["P01"]=1;a=Bonus.draw(g,"research:queued1",V.Arr(),V.Map("kind","research","bonus_ids",V.Arr("P01")));b=Bonus.draw(g,"research:queued2",V.Arr(),V.Map("kind","research","bonus_ids",V.Arr("P01")));Bonus.choose(g,a["reward_id"].Text,"P01");Check(Bonus.choose(g,b["reward_id"].Text,"P01")!=""&&Bonus.pending(g)[0]["kind"]=="copy","stale queued research retains fallback offer");Check(Bonus.choose(g,b["reward_id"].Text,"P01")=="","stale fallback remains claimable");
 }
 static void ThemeScenarios() {
  var g=Fresh();Check(Themes._themes(g).Count==5&&Themes._events(g).Count==21,"five themes twenty-one events");string state=g.s.ToJson();Themes.view(g);Themes.view(g);Check(g.s.ToJson()==state,"theme rendering is read-only");int revision=g.revision;Check(Themes.select(g,"agricultural")==""&&g.revision==revision+1,"select invalidates revision");revision=g.revision;Check(Themes.select(g,"industrial")!=""&&g.revision==revision,"reject free switching without revision");Hold(g,.5);Check(Theme(g)["steady_seconds"].Double==0,"first endpoint cannot credit elapsed hold");Hold(g,.5);Check(Near(Theme(g)["steady_seconds"].Double,.5*Cycles.MONTH_SECONDS),"consecutive endpoint credits hold");double elapsed=Theme(g)["steady_seconds"].Double;Themes.tick(g,.5*Cycles.MONTH_SECONDS);Check(Theme(g)["steady_seconds"].Double==elapsed,"same receipt not counted twice");g.s["simulation_tick"]=g.s["simulation_tick"].Long+1;g.s["audit"]["resources"]["food"]["produced"]=0.0;Themes.tick(g,.5*Cycles.MONTH_SECONDS);Check(Theme(g)["steady_seconds"].Double==0,"imports cannot count as local food production");Hold(g,.1);Hold(g,1);Check(Theme(g)["stage"].Long==2&&Theme(g)["milestone_ids"].Contains("agricultural:M1"),"earned M1 advances stage");int rewardCount=g.s["block"]["reward_choices"].Count;Theme(g)["reforge_tokens"]=2;g.s["dt"]=7.49;state=g.s.ToJson();Check(Themes.reforge(g,"industrial")!=""&&g.s.ToJson()==state,"insufficient DT no partial mutation");g.s["dt"]=30.0;Check(Themes.reforge(g,"industrial")==""&&Theme(g)["reforge_tokens"].Long==1&&Near(g.s["dt"].Double,22.5),"reforge consumes token and 7.5 DT");Check(Themes.reforge(g,"agricultural")==""&&Theme(g)["stage"].Long==2,"return skips earned milestone");Check(g.s["block"]["reward_choices"].Count==rewardCount,"reforge preserves queue");
  g=Fresh();g.s["block"]["trade_history"]=V.Arr(V.Map("amount",1000.0,"side","sell","resource","food"));Themes.select(g,"logistics");Hold(g,.1);Check(Theme(g)["counters"].Get("trade",0).Double==0,"preselection trade excluded");g.s["block"]["trade_history"].Add(V.Map("amount",12.0,"side","buy","resource","food"));Hold(g,.1);Check(Theme(g)["stage"].Long==2&&Theme(g)["counters"].Get("trade",0).Double==0,"M1 trade not carried into M2");g.s["block"]["trade_history"].Add(V.Map("amount",48.0,"side","sell","resource","goods"));Hold(g,1);Check(Theme(g)["stage"].Long==3,"either trade direction counts with stable food");g.s["block"]["trade_history"].Add(V.Map("amount",96.0,"side","buy","resource","material"));g.s["currency"]=100;g.s["projects"]["municipal"]["inventory"]["food"]=40;Hold(g,.1);Check(Theme(g)["completed"].Bool,"logistics completion uses cash and food reserve");Theme(g)["reforge_tokens"]=1;Check(Themes.reforge(g,"civic")!="","completed theme locked");
  g=Fresh();Themes.select(g,"industrial");var e=Offer(g,"industrial_equipment");g.s["currency"]=59;state=g.s.ToJson();Check(Themes.choose_event(g,e["id"].Text,"accept")!=""&&g.s.ToJson()==state,"equipment insufficient cash retains materials");g.s["currency"]=100;g.s["projects"]["municipal"]["inventory"]["material"]=20;rewardCount=g.s["block"]["reward_choices"].Count;revision=g.revision;Check(Themes.choose_event(g,e["id"].Text,"accept")==""&&g.s["currency"].Double==40&&g.s["block"]["reward_choices"].Count==rewardCount+1&&g.revision==revision+1,"equipment pays once queues real copy");Check(Themes.choose_event(g,e["id"].Text,"accept")!="","event cannot repay/reaward");e=Offer(g,"industrial_order");g.s["currency"]=100;Check(Themes.choose_event(g,e["id"].Text,"accept")==""&&g.s["currency"].Double==80,"20 escrow contract");g.s["projects"]["municipal"]["inventory"]["goods"]=20;Check(Themes.deliver(g,"",-1,e["id"].Text)==""&&g.s["currency"].Double==180,"delivery refunds escrow and cash reward");
  g=Fresh();Themes.select(g,"industrial");e=Offer(g,"industrial_order");g.s["currency"]=100;Themes.choose_event(g,e["id"].Text,"accept");Hold(g,3);Check(e["status"]=="failed"&&g.s["currency"].Double==80,"exact deadline fails undelivered escrow");state=g.s.ToJson();var history=Themes.view(g)["history"][-1];Check(history["name"]=="大宗订单"&&history["status_label"]=="逾期未达成"&&history["reason"].Text!="","event history explains failure");Check(g.s.ToJson()==state,"history projection read-only");
  g=Fresh();Themes.select(g,"civic");e=Offer(g,"civic_families");Themes.choose_event(g,e["id"].Text,"accept");double people=Themes._population_metrics(g)["population"].Double;Hold(g,.5);Check(Near(Themes._population_metrics(g)["population"].Double,people),"migrants wait until local month");Hold(g,.5);Check(Near(Themes._population_metrics(g)["population"].Double,people+6),"six actual migrants at month boundary");Hold(g,.5);Check(Near(Themes._population_metrics(g)["population"].Double,people+6),"arrival no replay");
  g=Fresh();Themes.select(g,"industrial");e=Offer(g,"industrial_order");g.s["currency"]=100;Themes.choose_event(g,e["id"].Text,"accept");Theme(g)["reforge_tokens"]=1;g.s["dt"]=30;Themes.reforge(g,"civic");Check(e["status"]=="cancelled"&&g.s["currency"].Double==100,"reforge refunds unfinished escrow");
  g=Fresh();Themes.select(g,"industrial");Theme(g)["reforge_tokens"]=1;g.s["dt"]=7.5;Check(Themes.reforge(g,"civic")==""&&g.s["dt"].Double==0&&g.s["block"]["ending"]["triggered"].Bool,"exact reforge cost closes DT");
 }
 static void CyclesAndEnding() {
  var g=Fresh();var catalogCapstones=catalog.capstones.ToJson();var detachedDefinitions=Block.capstone_definitions(g);detachedDefinitions["industrial"]["name"]="changed";Check(catalog.capstones.ToJson()==catalogCapstones,"capstone definitions detached from authored catalog");g.s["metrics"]["housed"]=32.0;Cycles.tick(g,Cycles.MONTH_SECONDS,26);Check(g.s["block"]["cycles"]["population_stability"]["32"].Double==0,"endpoint migrants receive no preceding stability");Cycles.tick(g,Cycles.MONTH_SECONDS-1,32);Check(!g.s["block"]["cycles"]["population_awards"].Contains("32"),"one second short no population award");Cycles.tick(g,1,32);Check(g.s["block"]["cycles"]["population_awards"].Contains("32"),"actual stable month grants award");Cycles.tick(g,1,32);Check(g.s["block"]["reward_choices"].Count(x=>x["source"]=="population:32")==1,"population award once");g.s["beta_time"]["local_elapsed_seconds"]=Cycles.YEAR_SECONDS*2;Cycles.tick(g,1,32);Check(g.s["block"]["cycles"]["year"].Long==2&&g.s["block"]["cycles"]["major_cycle"].Long==1,"annual catchup and two year chapter");Check(g.s["block"]["cycles"]["pending_summaries"].Count==2&&g.s["settings"]["user_paused"].Bool,"annual summaries and pause");Cycles.acknowledge(g);Check(g.s["block"]["cycles"]["pending_summaries"].Count==0&&g.s["block"]["cycles"]["history"].Count==2,"acknowledge keeps history");
  g=Fresh();Themes.select(g,"industrial");g.s["dt"]=0.0;Block.on_dt_zero(g);string ending=g.s["block"]["ending"].ToJson();Theme(g)["completed"]=true;Block.on_dt_zero(g);Check(g.s["block"]["ending"].ToJson()==ending&&Block.claim_capstone(g)!="","late completion no retroactive capstone");Check(Block.name_block(g,"新河谷")==""&&Block.name_block(g,"再命名")!="","universal naming right once");
  g=Fresh();Themes.select(g,"industrial");Theme(g)["completed"]=true;g.s["dt"]=0.0;Block.on_dt_zero(g);string cells=g.s["cells"].ToJson(),projects=V.From(g.s["projects"].Keys).ToJson();Check(Block.claim_capstone(g)=="","eligible capstone claim");Check(g.s["cells"].ToJson()==cells&&V.From(g.s["projects"].Keys).ToJson()==projects,"capstone consumes no cell or building");Check(Block.claim_capstone(g)!="","capstone once");g.storageRoot="";Check(!Block.archive(g)["ok"].Bool,"archive without injected path refuses");g.storageRoot=recordsRoot;var archived=Block.archive(g);Check(archived["ok"].Bool&&File.Exists(archived["path"].Text)&&archived["record"]["read_only"].Bool,"actual archive persisted under injected path");Check(Block.archive(g)["existing"].Bool,"archive reuses immutable record");Check(Block.list_archives(g).Count>0,"archive list reads record");
  g=Fresh();g.s["dt"]=0.0;Block.on_dt_zero(g);g.s["block"]["ending"]["archive_id"]="corrupt-check";var badPath=Path.Combine(recordsRoot,"city_records","corrupt-check.json");File.WriteAllText(badPath,"{\"id\":\"corrupt-check\",\"read_only\":false,\"city_state\":\"bad\"}");var before=g.s.ToJson();Check(!Block.archive(g)["ok"].Bool&&g.s.ToJson()==before,"corrupt existing archive preserves city");Check(File.ReadAllText(badPath).Contains("\"read_only\":false"),"corrupt existing record preserved");
 }
 public static int Run(Catalog c,string isolatedRecordsRoot) {catalog=c;recordsRoot=isolatedRecordsRoot;checks=failures=0;Rewards();ThemeScenarios();CyclesAndEnding();Console.WriteLine($"PROGRESSION RESULT {checks-failures}/{checks} passed");return failures;}
}
